function sumOfFlooredPairs(nums) {
  const MOD = 1_000_000_007;
  let maxValue = 0;
  for (const num of nums) {
    maxValue = Math.max(maxValue, num);
  }
  const prefix = new Array(maxValue + 1).fill(0);
  for (const num of nums) {
    prefix[num]++;
  }
  for (let value = 1; value <= maxValue; value++) {
    prefix[value] += prefix[value - 1];
  }
  let total = 0;
  for (let divisor = 1; divisor <= maxValue; divisor++) {
    const count = prefix[divisor] - prefix[divisor - 1];
    if (count === 0) {
      continue;
    }
    for (let low = divisor; low <= maxValue; low += divisor) {
      const high = Math.min(low + divisor - 1, maxValue);
      const inRange = prefix[high] - prefix[low - 1];
      const quotient = low / divisor;
      total = (total + count * quotient * inRange) % MOD;
    }
  }
  return total;
}

